create table if not exists venue_products(id uuid primary key default gen_random_uuid(),venue_id uuid not null references venues(id) on delete cascade,category text not null,name text not null,description text,base_price numeric(12,2),price_type text not null default 'fixed',is_active boolean not null default true,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists venue_policies(id uuid primary key default gen_random_uuid(),venue_id uuid not null references venues(id) on delete cascade,policy_key text not null,title text not null,content text,metadata jsonb not null default '{}'::jsonb,unique(venue_id,policy_key));